import math, itertools
import numpy as np

I2 = np.eye(2); X = np.array([[0, 1], [1, 0]], dtype=complex); Y = np.array([[0, -1j], [1j, 0]]); Z = np.array([[1, 0], [0, -1]], dtype=complex)
H = np.array([[1, 1], [1, -1]], dtype=complex) / math.sqrt(2)
def kron(*ms):
    out = np.array([[1.0 + 0j]])
    for m in ms: out = np.kron(out, m)
    return out
def ket(bits):
    v = np.zeros(2 ** len(bits), dtype=complex); v[int("".join(map(str, bits)), 2)] = 1; return v
def proj(v):
    return np.outer(v, v.conj())
PHI_PLUS = (ket([0, 0]) + ket([1, 1])) / math.sqrt(2)
BELL = {"phi+": PHI_PLUS, "phi-": (ket([0, 0]) - ket([1, 1])) / math.sqrt(2), "psi+": (ket([0, 1]) + ket([1, 0])) / math.sqrt(2), "psi-": (ket([0, 1]) - ket([1, 0])) / math.sqrt(2)}
def werner(w, target=PHI_PLUS):
    # w * |target><target| + (1 - w) * I / 4: the noisy entangled pair used throughout; w is the Werner parameter, the fidelity with the target is (1 + 3 w) / 4
    return w * proj(target) + (1 - w) * np.eye(4) / 4
def fidelity_pure(rho, v):
    return float((v.conj() @ rho @ v).real)
def ptrace(rho, dims, keep):
    n = len(dims); t = rho.reshape(dims + dims)
    for i in sorted([i for i in range(n) if i not in keep], reverse=True):
        t = np.trace(t, axis1=i, axis2=i + t.ndim // 2)
    d = int(np.prod([dims[i] for i in keep])); return t.reshape(d, d)
def apply_unitary(rho, U):
    return U @ rho @ U.conj().T
def op_on(n, gate, qubits):
    # a gate (given as a matrix on len(qubits) qubits) acting on the listed qubits of an n-qubit system, identity elsewhere
    k = len(qubits); dim = 2 ** n
    U = np.zeros((dim, dim), dtype=complex)
    for col in range(dim):
        bits = [(col >> (n - 1 - i)) & 1 for i in range(n)]
        sub = int("".join(str(bits[q]) for q in qubits), 2)
        for row_sub in range(2 ** k):
            amp = gate[row_sub, sub]
            if abs(amp) < 1e-15: continue
            nb = bits.copy()
            for j, q in enumerate(qubits): nb[q] = (row_sub >> (k - 1 - j)) & 1
            U[int("".join(map(str, nb)), 2), col] += amp
    return U
# --- the photon-loss channel: a photon travels through a fibre with attenuation alpha (dB/km); it arrives with probability eta = 10^(-alpha L / 10)
def eta(length_km, alpha=0.2):
    return 10 ** (-alpha * length_km / 10)
# loss on a dual-rail (polarisation or time-bin) qubit: with probability 1 - eta the photon is lost and a flag says so (an ERASURE), with probability eta the state arrives intact
print(f"{'distance L (km)':>16} {'transmission eta = 10^(-0.2 L/10)':>34} {'one-photon-per-pulse rate limit eta':>38} {'PLOB bound -log2(1 - eta) (bits per use)':>42}")
for L in (10, 50, 100, 200, 300, 500, 1000):
    e = eta(L)
    print(f"{L:>16} {e:>34.3e} {e:>38.3e} {-math.log1p(-e) / math.log(2):>42.3e}")
print("fibre loss is exponential in distance: 0.2 dB/km means -20 dB (a factor 100) every 100 km; the PLOB bound (Pirandola, Laurenza, Ottaviani, Banchi) says that no repeaterless protocol can send more than about 1.44 eta secret or quantum bits per use of a lossy channel")

# --- a lossy channel is an ERASURE channel for a dual-rail qubit: simulate the state that arrives, conditioned on arrival, for a Bell pair half sent through it
def send_half_through_fibre(rho_pair, transmission, dephase=0.0):
    # the second qubit of the pair travels; with probability (1 - transmission) the photon is lost (the output is flagged and discarded), otherwise it arrives, possibly dephased
    p_arrive = transmission
    arrived = rho_pair
    if dephase > 0:
        Zb = kron(I2, Z)
        arrived = (1 - dephase) * arrived + dephase * (Zb @ arrived @ Zb)
    return p_arrive, arrived
rho = proj(PHI_PLUS)
print()
print(f"{'L (km)':>8} {'P(photon arrives)':>19} {'fidelity of the delivered pair (dephasing 0.5% per 10 km)':>60}")
for L in (10, 50, 100, 200):
    p_arrive, state = send_half_through_fibre(rho, eta(L), dephase=0.005 * L / 10)
    print(f"{L:>8} {p_arrive:>19.4f} {fidelity_pure(state, PHI_PLUS):>60.4f}")
print("loss reduces the RATE (the pair is simply not delivered, and the sender can tell); dephasing reduces the FIDELITY of the pairs that are delivered: the two have different remedies (repeaters and memories for loss, purification for noise)")

# --- direct transmission rate for a source emitting pairs at 1 GHz, per second, against distance
print()
print(f"{'L (km)':>8} {'delivered pairs per second at 1 GHz':>38} {'seconds per pair':>18}")
for L in (50, 100, 200, 400, 600, 1000):
    rate = 1e9 * eta(L)
    print(f"{L:>8} {rate:>38.3e} {1 / rate:>18.3e}")
print("at 1000 km a direct link would deliver one pair per 10^11 seconds (about 3,000 years): the reason satellites (loss grows slowly with distance in free space) and quantum repeaters are needed for long distances")

