# --- how the pair gets degraded on the way: one half goes through a depolarizing channel with parameter lambda
def depolarize_second_half(rho, lam):
    # (1 - lam) rho + lam * (trace out qubit 2, replace it with the maximally mixed state)
    reduced = ptrace(rho, [2, 2], [0])
    return (1 - lam) * rho + lam * np.kron(reduced, np.eye(2) / 2)
