# --- the effect of a memory cutoff: discard pairs older than the cutoff. Trade-off between the fidelity of the delivered pair and the waiting time.
rng = np.random.default_rng(46)
def two_link_experiment(p, T2_slots, cutoff, trials=20000):
    # two links, each succeeds with probability p per slot; once both exist they are swapped immediately; a stored link older than `cutoff` slots is discarded
    fidelities, times = [], []
    for _ in range(trials):
        ages = [None, None]; t = 0
        while True:
            t += 1
            for i in range(2):
                if ages[i] is None:
                    if rng.random() < p: ages[i] = 0
                else:
                    ages[i] += 1
                    if ages[i] > cutoff: ages[i] = None
            if ages[0] is not None and ages[1] is not None:
                w = math.exp(-ages[0] / T2_slots) * math.exp(-ages[1] / T2_slots)           # each stored half dephases while it waits
                fidelities.append((1 + 3 * w) / 4); times.append(t); break
    return float(np.mean(fidelities)), float(np.mean(times))
print()
print(f"{'cutoff (slots)':>15} {'mean fidelity of the swapped pair':>35} {'mean waiting time (slots)':>27}   (p = 0.02 per slot, T2 = 200 slots)")
