from collections import deque

# --- a small quantum network as a graph: nodes are repeater stations and users, edges are fibre links with a heralded pair generation rate (pairs per second) -- DEMO DATA
links = {("A", "R1"): 40, ("A", "R2"): 25, ("R1", "R2"): 15, ("R1", "R3"): 30, ("R2", "R3"): 20, ("R2", "R4"): 20, ("R3", "B"): 35, ("R4", "B"): 25, ("R3", "R4"): 10}
print("DEMO DATA: invented link rates in pairs per second, for illustrating the algorithms (not measurements)")
nodes = sorted({n for e in links for n in e})
capacity = {}
for (u, v), r in links.items():
    capacity[(u, v)] = capacity.get((u, v), 0) + r
    capacity[(v, u)] = capacity.get((v, u), 0) + r                              # a link produces pairs for both directions of use

# the entanglement flow between A and B: each end-to-end pair uses one pair on every link of its path (one swap at each intermediate node), so the maximum number of pairs per second is a max-flow
def max_flow(cap, s, t):
    residual = dict(cap); flow = 0; paths = []
    while True:
        parent = {s: None}; queue = deque([s])
        while queue and t not in parent:
            u = queue.popleft()
            for (a, b), c in residual.items():
                if a == u and c > 1e-12 and b not in parent:
                    parent[b] = u; queue.append(b)
        if t not in parent: break
        path = []; v = t
        while parent[v] is not None:
            path.append((parent[v], v)); v = parent[v]
        path.reverse()
        bottleneck = min(residual[e] for e in path)
        for (a, b) in path:
            residual[(a, b)] -= bottleneck; residual[(b, a)] = residual.get((b, a), 0) + bottleneck
        flow += bottleneck; paths.append((bottleneck, [path[0][0]] + [e[1] for e in path]))
    return flow, paths
single_path_rate = 0
def best_single_path(cap, s, t):
    best = (0, None)
    def dfs(u, visited, rate, route):
        nonlocal best
        if u == t:
            if rate > best[0]: best = (rate, route)
            return
        for (a, b), c in cap.items():
            if a == u and b not in visited:
                dfs(b, visited | {b}, min(rate, c), route + [b])
    dfs(s, {s}, float("inf"), [s])
    return best
single_rate, single_route = best_single_path(capacity, "A", "B")
total_flow, used = max_flow(capacity, "A", "B")
print()
print(f"best single route from A to B: {'-'.join(single_route)} with a bottleneck rate of {single_rate} pairs per second")
print(f"maximum rate with multipath routing: {total_flow} pairs per second ({total_flow / single_rate:.2f} times the best single route), using these augmenting paths:")
for rate, path in used:
    print(f"   {rate:>4} pairs/s along {'-'.join(path)}")
# the min cut certifies the maximum: the cut separating A from B with the smallest total capacity
def min_cut_value(cap, s, t):
    best = float("inf")
    others = [n for n in nodes if n not in (s, t)]
    for mask in range(2 ** len(others)):
        S = {s} | {others[i] for i in range(len(others)) if mask >> i & 1}
        value = sum(c for (a, b), c in cap.items() if a in S and b not in S)
        best = min(best, value)
    return best
print("the max-flow equals the minimum cut capacity (the narrowest bottleneck between A and B):", min_cut_value(capacity, "A", "B"), "pairs per second")
print("this treats the pairs as a CLASSICAL flow of resources; the quantum no-cloning constraint appears as the rule that each pair is consumed by exactly one swap, so flows cannot be copied or multicast without butterfly-type tricks")

